湊

global save.好感度 ?= 0

OnBoot => {
    湊: こんにちは。今日の気分は？
    \q[いい,OnMoodGood]
    \q[わるい,OnMoodBad]
}

OnMoodGood => {
    global save.好感度 += 1
    湊: よかった。好感度は${save.好感度}です。
